<script>
 import Icon from './Icon.svelte';import {formatValue} from '$lib/energy';
 let {metrics={}}=$props();
 let solar=$derived(metrics?.solar?.value??null);let usage=$derived(metrics?.consumption?.value??null);let battery=$derived(metrics?.batteryPower?.value??null);let grid=$derived(metrics?.grid?.value??null);
 const power=(value)=>value===null?'Not reported':formatValue(value/1000,'kW',2);
</script>
<div class="energy-flow"><div class="flow-source solar-source"><span class="flow-icon solar-icon"><Icon name="sun" size={25}/></span><div><small>Solar power</small><strong>{power(solar)}</strong></div></div><div class="flow-connector solar-connector"><span>{solar!==null&&solar>0?'→':'—'}</span></div><div class="flow-home"><span class="flow-icon home-icon"><Icon name="home" size={31}/></span><small>Your home</small><strong>{power(usage)}</strong><span>Consumption</span></div><div class="flow-source battery-source"><span class="flow-icon"><Icon name="battery" size={25}/></span><div><small>Battery</small><strong>{power(battery===null?null:Math.abs(battery))}</strong><span>{battery===null?'Direction unavailable':battery>0?'Charging':battery<0?'Discharging':'Idle'}</span></div></div><div class="flow-connector battery-connector"><span>{battery===null||battery===0?'—':battery>0?'←':'→'}</span></div><div class="flow-source grid-source"><span class="flow-icon"><Icon name="grid" size={25}/></span><div><small>Grid connection</small><strong>{power(grid===null?null:Math.abs(grid))}</strong><span>{grid===null?'Not reported':grid>0?'Importing':grid<0?'Exporting':'No transfer'}</span></div></div><div class="flow-connector grid-connector"><span>{grid===null||grid===0?'—':grid>0?'↑':'↓'}</span></div></div><p class="flow-footnote">Source readings, not a measurement of individual source-to-home transfers. Battery and grid direction follow reported power signs.</p>
